<script setup lang="ts">
import { useCourseDonations, type CourseDonation } from '~/composables/useCourseDonations'
import Dialog from 'primevue/dialog'
definePageMeta({ layout: 'main', middleware: ['auth', 'plearnd-admin'] }); const { adminList, adminApprove, adminReject } = useCourseDonations(); const rows = ref<CourseDonation[]>([]); const meta = ref<any>({}); const loading = ref(true); const selected = ref<CourseDonation | null>(null); const reason = ref(''); const showReject = ref(false)
const load = async (page = 1) => { loading.value = true; try { const r = await adminList({ page }); rows.value = r.data; meta.value = r.meta } finally { loading.value = false } }; onMounted(() => load())
const approve = async (row: CourseDonation) => { await adminApprove(row.id); await load(meta.value.current_page || 1) }; const reject = async () => { if (!selected.value || !reason.value.trim()) return; await adminReject(selected.value.id, reason.value); showReject.value = false; reason.value = ''; await load(meta.value.current_page || 1) }; const amount = (r: CourseDonation) => r.donation_type === 'point' ? `${r.points_amount} points` : `${r.cash_amount} ${r.currency || 'THB'}`
</script>
<template><div class="mx-auto max-w-7xl space-y-6 p-6"><h1 class="text-2xl font-bold">Course donation queue</h1><div class="overflow-hidden rounded-2xl bg-white shadow dark:bg-slate-800"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 dark:bg-slate-700"><tr><th class="p-4">ID</th><th class="p-4">Course</th><th class="p-4">Donor</th><th class="p-4">Type</th><th class="p-4">Amount</th><th class="p-4">Status</th><th class="p-4">Slip</th><th class="p-4">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="8" class="p-8 text-center">Loading…</td></tr><tr v-for="row in rows" :key="row.id" class="border-t dark:border-slate-700"><td class="p-4">{{ row.id }}</td><td class="p-4">{{ row.course?.name || row.course_id }}</td><td class="p-4">{{ row.donor_display_name || 'ผู้ไม่ประสงค์ออกนาม' }}</td><td class="p-4">{{ row.donation_type }}</td><td class="p-4">{{ amount(row) }}</td><td class="p-4">{{ row.status }}</td><td class="p-4"><a v-if="row.slip_url" :href="row.slip_url" target="_blank" class="text-primary-600">View</a><span v-else>—</span></td><td class="space-x-2 p-4"><button v-if="row.status === 'pending'" class="min-h-[44px] sm:min-h-0 rounded bg-emerald-600 px-3 py-1 text-white" @click="approve(row)">Approve</button><button v-if="row.status === 'pending'" class="min-h-[44px] sm:min-h-0 rounded bg-red-600 px-3 py-1 text-white" @click="selected = row; showReject = true">Reject</button></td></tr></tbody></table></div></div><Dialog v-model:visible="showReject" modal header="Reject donation" class="w-full max-w-md"><textarea v-model="reason" class="w-full rounded-lg border p-3" placeholder="Reason" /><button class="mt-3 w-full rounded-lg bg-red-600 p-3 text-white" @click="reject">Reject</button></Dialog></div></template>
